CREATE TABLE lectures (
                          lecture_id BIGSERIAL PRIMARY KEY,
                          title      VARCHAR(200) NOT NULL,
                          topic      VARCHAR(100) NOT NULL,
                          content    TEXT         NOT NULL
);

INSERT INTO lectures (title, topic, content) VALUES
                                                 ('Введение в матрицы', 'Алгебра', 'Матрица — это прямоугольная таблица чисел, расположенных в строках и столбцах. Матрицы используются для компактной записи систем линейных уравнений, линейных преобразований и во многих других разделах математики.'),
                                                 ('Определители и их свойства', 'Алгебра', 'Определитель — это число, которое можно вычислить для квадратной матрицы. Он показывает, обратима ли матрица: если определитель равен нулю, обратной матрицы не существует.'),
                                                 ('Производная функции', 'Анализ', 'Производная функции в точке характеризует скорость изменения функции в этой точке. Геометрически производная равна тангенсу угла наклона касательной к графику функции.');